import pandas as pd

internal_transactions = pd.DataFrame({
    "customer_id": [101, 102, 103],
    "purchase_amount": [59.99, 120.00, 34.50],
})

public_demographics = pd.DataFrame({
    "customer_id": [101, 102, 103],
    "region": ["north", "south", "north"],
})

combined = internal_transactions.merge(public_demographics, on="customer_id")
print(combined)
